        score[s] = max(.02, score[s]) * (.95 + .05*data.get(s, {}).get("invvol", med_invvol)/max(med_invvol, 1e-12))
    target = bounded_weights(score)
    if abs(sum(target.values())-1.0) < 1e-8 and all(np.isfinite(v) and v >= 0 for v in target.values()):
        rebalance_to_weights(target)

