           "clvtrend15": .067, "cons_mom20": .056, "eff20": .033,
           "rev3": .033}
MIN_W, MAX_W = .02, .15
_day = 0

def rank_cs(vals):
    out = {s: .5 for s in ASSETS}
    good = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out

def bounded(score):
    # Start at the required floor, then distribute the remaining capital.
    w = {s: MIN_W for s in ASSETS}
    free, active = 1.0 - MIN_W * len(ASSETS), set(ASSETS)
    while active and free > 1e-12:
        q = {s: max(float(score.get(s, .5)), .01) for s in active}
        total = sum(q.values())
        capped = [s for s in active if free * q[s] / total > MAX_W - MIN_W]
        if not capped:
            for s in active:
                w[s] += free * q[s] / total
            break
        for s in capped:
            w[s] = MAX_W
            free -= MAX_W - MIN_W
            active.remove(s)
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}

