# Current screener ensemble; all directions are positive.
FACTORS = {"mom20": .24, "mom30": .18, "resid30": .14, "downmom": .12,
           "eff": .11, "persist": .09, "lead": .07, "rev": .05}
MIN_W, MAX_W = .02, .14
_day = 0

def rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.) / n
    return out

def bounded(raw):
    # Floors and caps prevent correlated momentum from creating concentration.
    raw = {s: max(float(raw.get(s, .5)), .05) for s in ASSETS}
    w = {s: MIN_W + (1 - MIN_W*len(ASSETS))*raw[s]/sum(raw.values()) for s in ASSETS}
    for _ in range(10):
        excess = sum(max(0., w[s]-MAX_W) for s in ASSETS)
        if excess < 1e-10: break
        capped = {s for s in ASSETS if w[s] >= MAX_W-1e-10}
        for s in capped: w[s] = MAX_W
        free = [s for s in ASSETS if s not in capped]
        if not free: break
        z = sum(raw[s] for s in free)
        for s in free: w[s] += excess*raw[s]/z
    z = sum(w.values())
    return {s: w[s]/z for s in ASSETS}

@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % 10 != 0:
        return
    data = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=180)
