                   "lead_raw": t5, "vol": v20}
    if len(data) < 10:
        return
    med5 = np.median([x["lead_raw"] for x in data.values()])
    med30 = np.median([x["t30"] for x in data.values()])
    for x in data.values():
        x["lead"] = x["lead_raw"] - med5
        x["resid"] = x["t30"] - med30
    ranks = {f: rank_cs({s: x[f] for s, x in data.items()}) for f in FACTORS}
