FACTORS = {
    "eff20": .20, "mom30": .15, "down20": .15, "rev1": .12,
    "mom20c": .10, "resid30": .10, "ram20": .08,
    "persist30": .07, "clv1": .03
}
REBALANCE_DAYS = 10
POSITION_SCALING = .45
MIN_W, MAX_W = .04, .14
_day = 0


def cs_rank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    if not valid:
        return out
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n
    return out


def bounded_weights(score, invvol):
    raw = {s: max(.10, .5 + POSITION_SCALING * (score[s] - .5)) *
              np.clip(invvol.get(s, 1.), .70, 1.30) for s in ASSETS}
    w = {s: MIN_W + (1 - len(ASSETS) * MIN_W) * raw[s] / sum(raw.values()) for s in ASSETS}
    # Iterative capped redistribution; preserves a complete, long-only vector.
    for _ in range(20):
        over = [s for s in ASSETS if w[s] > MAX_W + 1e-10]
        if not over:
            break
        excess = sum(w[s] - MAX_W for s in over)
        for s in over:
            w[s] = MAX_W
        free = [s for s in ASSETS if s not in over]
        den = sum(raw[s] for s in free)
        if not free or den <= 0:
            break
        for s in free:
            w[s] += excess * raw[s] / den
    z = sum(w.values())
    return {s: max(0., w[s] / z) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % REBALANCE_DAYS != 0:
        return

    features = {}
    for s in ASSETS:
