    breadth = float(np.mean([features[s]["t30"] > 0 for s in eq])) if eq else .5
    market_vol = float(np.median([v["vol"] for v in features.values()]))
    # Bear/high-risk posture: defensive tradable assets replace cash; risk assets are capped indirectly.
