# Current screener ensemble: eight active factors, all implemented with lagged bars.
FACTORS = {"peer": .18, "eff": .18, "mom20": .16, "down": .14,
           "rev": .12, "mom30": .10, "resid": .10, "clv": .02}
REBALANCE_DAYS = 10
POSITION_SCALING = .42
MIN_W, MAX_W = .04, .14
_day = 0


def rank_cs(x):
    good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.) / n
    return out


def make_weights(score, invvol):
    raw = {s: max(.12, .5 + POSITION_SCALING * (score[s] - .5)) *
              np.clip(invvol.get(s, 1.), .72, 1.28) for s in ASSETS}
    w = {s: MIN_W + (1 - len(ASSETS) * MIN_W) * raw[s] / sum(raw.values()) for s in ASSETS}
    for _ in range(30):
        over = [s for s in ASSETS if w[s] > MAX_W + 1e-12]
        if not over:
            break
        excess = sum(w[s] - MAX_W for s in over)
        for s in over:
            w[s] = MAX_W
        free = [s for s in ASSETS if s not in over]
        den = sum(raw[s] for s in free)
        if not free or den <= 0:
            break
        for s in free:
            w[s] += excess * raw[s] / den
    z = sum(w.values())
    return {s: max(0., w[s] / z) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % REBALANCE_DAYS:
        return
    f = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=100)
        if df is None or len(df) < 70:
            continue
        df = df.sort_values("date")
        # The last bar can be in progress; only completed bars are used.
        c = np.asarray(df["close"], dtype=float)[:-1]
        hi = np.asarray(df["high"], dtype=float)[:-1]
        lo = np.asarray(df["low"], dtype=float)[:-1]
        if len(c) < 65 or np.any(c[-65:] <= 0):
            continue
        r = c[1:] / c[:-1] - 1.
        v20 = max(float(np.std(r[-20:])), .006)
        dn20 = max(float(np.std(np.minimum(r[-20:], 0))), .003)
        t5 = c[-1] / c[-6] - 1.
        t20 = c[-1] / c[-21] - 1.
        t30 = c[-1] / c[-31] - 1.
        p20, p30 = np.mean(r[-20:] > 0), np.mean(r[-30:] > 0)
        # Smoothed one-day reversal and close-location value.
        rev = float(np.mean(-r[-3:]) / (v20 + .01))
        clv = float(np.mean((2*c[-3:] - hi[-3:] - lo[-3:]) /
                            np.maximum(hi[-3:] - lo[-3:], c[-3:] * .001)))
        f[s] = {"peer": t5, "eff": t20 / (dn20 + .015),
                "mom20": t20 / (v20 + .01) * (.5 + p20),
                "down": t20 / (dn20 + .01), "rev": rev,
                "mom30": t30 / (v20 + .01) * (.5 + p30),
                "clv": clv, "v": v20, "t30": t30}
    if len(f) < 10:
        return
    # Peer-median lead-lag: favor assets leading their cross-asset peers over 5 days.
    med5 = float(np.median([v["peer"] for v in f.values()]))
    # Market-residual momentum removes the equity-benchmark component.
    eq = [s for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX") if s in f]
    med30 = float(np.median([f[s]["t30"] for s in eq])) if eq else 0.
    for v in f.values():
        v["peer"] -= med5
        v["resid"] = v["t30"] - med30
    ranks = {k: rank_cs({s: v.get(k, np.nan) for s, v in f.items()}) for k in FACTORS}
    score = {s: sum(FACTORS[k] * ranks[k][s] for k in FACTORS) for s in ASSETS}
    breadth = np.mean([f[s]["t30"] > 0 for s in eq]) if eq else .5
    market_vol = float(np.median([v["v"] for v in f.values()]))
    # Bear/high-risk expression uses defensive tradable instruments, never cash.
    if breadth < .50 or market_vol > .018:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .12
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .06
    invvol = {s: np.clip(market_vol / max(v["v"], .006), .72, 1.28) for s, v in f.items()}
    rebalance_to_weights(make_weights(score, invvol))


def strategy():
    return cross_asset_strategy()

