import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Current screener ensemble (eight factors; all positive direction).
FACTORS = {"mom30": .20, "mom20": .18, "lead5": .18, "mktres": .12,
           "persist30": .10, "dxyres": .09, "cons20": .08, "clv": .05}
REBALANCE_DAYS = 10
POSITION_SCALING = .065
MIN_W, MAX_W = .04, .14
_day = 0


def cs_rank(vals):
    out = {s: .5 for s in ASSETS}
    a = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.0) / len(a)
    return out


def weights(score, invvol):
    # Full investment, with a broad floor and a conservative score tilt.
    raw = {s: (.5 + POSITION_SCALING * (score[s] - .5)) *
              np.clip(invvol.get(s, 1.), .72, 1.28) for s in ASSETS}
    w = {s: MIN_W + (1 - len(ASSETS) * MIN_W) * raw[s] / sum(raw.values()) for s in ASSETS}
    for _ in range(25):
        high = [s for s in ASSETS if w[s] > MAX_W + 1e-12]
        if not high:
            break
        excess = sum(w[s] - MAX_W for s in high)
        for s in high:
            w[s] = MAX_W
        rest = [s for s in ASSETS if s not in high]
        z = sum(raw[s] for s in rest)
        if not rest or z <= 0:
            break
        for s in rest:
            w[s] += excess * raw[s] / z
    z = sum(w.values())
    return {s: max(0., w[s] / z) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % REBALANCE_DAYS != 0:
        return
    features, returns = {}, {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=160)
        if df is None or len(df) < 75:
            continue
        d = df.sort_values("date").iloc[:-1]  # lag the incomplete/current bar
        c = np.asarray(d["close"], float)
        if len(c) < 65 or np.any(~np.isfinite(c[-65:])) or np.any(c[-65:] <= 0):
            continue
        r = c[1:] / c[:-1] - 1.
        r5, r20, r30 = r[-5:], r[-20:], r[-30:]
        vol = max(float(np.std(r20)), .006)
        t20, t30 = c[-1] / c[-21] - 1., c[-1] / c[-31] - 1.
        consistency = float(np.mean(r20 > 0))
        # Persistence rewards positive, steady 30-day paths rather than a single jump.
        persist = t30 / (vol + .01) * (.5 + .5 * float(np.mean(r30 > 0)))
        clv = 0.
        if all(k in d.columns for k in ("high", "low", "close")):
            hi, lo, cc = [np.asarray(d[k].iloc[-10:], float) for k in ("high", "low", "close")]
            clv = float(np.mean(np.where(hi > lo, (2 * cc - hi - lo) / (hi - lo), 0.)))
        features[s] = {"mom30": t30 / (vol + .01), "mom20": t20 / (vol + .01),
                       "lead5": float(np.sum(r5)), "mktres": t30,
                       "persist30": persist, "dxyres": t30,
                       "cons20": consistency, "clv": clv, "t30": t30, "vol": vol}
        returns[s] = r[-30:]
    if len(features) < 10:
        return
    med5 = np.median([x["lead5"] for x in features.values()])
    med30 = np.median([x["t30"] for x in features.values()])
    for x in features.values():
        x["lead5"] -= med5
        x["mktres"] -= med30
    # DXY is observation-only and only enters as a residual signal.
    dxy = get_index_daily_data(symbol="DXY", days=160)
    if dxy is not None and len(dxy) > 35:
        dc = np.asarray(dxy.sort_values("date")["close"], float)[:-1]
        if len(dc) >= 31 and np.all(np.isfinite(dc[-31:])) and np.all(dc[-31:] > 0):
            dr = dc[1:] / dc[:-1] - 1.
            q, var = dr[-30:], np.var(dr[-30:])
            for s, x in features.items():
                ar = returns[s]
                beta = np.cov(ar, q, ddof=0)[0, 1] / var if var > 1e-10 else 0.
                x["dxyres"] = x["t30"] - beta * np.sum(q)
    ranks = {k: cs_rank({s: x[k] for s, x in features.items()}) for k in FACTORS}
    score = {s: sum(w * ranks[k][s] for k, w in FACTORS.items()) for s in ASSETS}
    breadth = np.mean([x["t30"] > 0 for x in features.values()])
    stress = breadth < .50 or np.median([x["vol"] for x in features.values()]) > .018
    if stress:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .38
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .25
    medvol = np.median([x["vol"] for x in features.values()])
    invvol = {s: medvol / x["vol"] for s, x in features.items()}
    rebalance_to_weights(weights(score, invvol))


def strategy():
    return cross_asset_strategy()

