    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.) / n
    return out


def weights(score, invvol):
    raw = {s: max(.05, .5 + POSITION_SCALING * (score[s] - .5)) *
              np.clip(invvol.get(s, 1.), .70, 1.30) for s in ASSETS}
    # A small floor preserves diversification across the deliberately small universe.
    w = {s: MIN_W + (1. - len(ASSETS) * MIN_W) * raw[s] / sum(raw.values())
