import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble: compression, stress, breadth, downside asymmetry,
# conditional reversal, and only a small trend component.
FW = {"compression": .30, "stress": .22, "breadth": .18,
      "asymmetry": .10, "reversal": .10, "quiet": .06, "relative": .04}
CADENCE = 10
_day = 0


def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in ASSETS}
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = i / (len(good) - 1)
    return out


def weights(score):
    # Full investment, diversified across the intentionally small universe.
    floor, cap = .02, .20
    b = {s: max(.01, float(score.get(s, .5))) for s in ASSETS}
    free = 1 - floor * len(ASSETS)
    w = {s: floor + free * b[s] / sum(b.values()) for s in ASSETS}
    for _ in range(20):
        high = [s for s in ASSETS if w[s] > cap]
        if not high:
            break
        excess = sum(w[s] - cap for s in high)
        for s in high:
            w[s] = cap
        low = [s for s in ASSETS if s not in high]
        z = sum(b[s] for s in low)
        for s in low:
            w[s] += excess * b[s] / max(z, 1e-12)
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % CADENCE != 0:
        return
    series = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None or len(df) < 100:
            continue
        c = np.asarray(df.sort_values("date").iloc[:-1]["close"], dtype=float)
        c = c[np.isfinite(c) & (c > 0)]
        if len(c) < 80:
            continue
        r = c[1:] / c[:-1] - 1
        neg = r[-60:][r[-60:] < 0]
        v10 = max(np.std(r[-10:]), .003)
        v20 = max(np.std(r[-20:]), .003)
        v60 = max(np.std(r[-60:]), .003)
        dv = max(np.std(neg) if len(neg) >= 3 else v20, .003)
        t10, t20, t30, t60 = (c[-1] / c[-n-1] - 1 for n in (10, 20, 30, 60))
        series[s] = dict(t10=t10, t20=t20, t30=t30, t60=t60,
                         v10=v10, v20=v20, v60=v60, dv=dv)
    if len(series) < 10:
        return

    raw = {f: {} for f in FW}
    for s, d in series.items():
        agree = np.mean([d["t10"] > 0, d["t20"] > 0, d["t60"] > 0])
        # Higher compression = recently quiet relative to its medium volatility.
        raw["compression"][s] = -d["v10"] / (d["v60"] + .003)
        # Defensive factors reward stable positive breadth and penalize downside risk.
        raw["stress"][s] = d["t10"] / (d["dv"] + .01)
        raw["breadth"][s] = d["t30"] * (.5 + .5 * agree) / (d["dv"] + .01)
        raw["asymmetry"][s] = -d["dv"] / (d["v60"] + .003)
        # Conditional reversal: only fade an isolated 10-day move in a broad move.
        raw["reversal"][s] = -d["t10"] if d["t30"] * d["t10"] < 0 else 0.0
        raw["quiet"][s] = d["t20"] / (d["v60"] + .01) * (.5 + .5 * agree)
        raw["relative"][s] = d["t20"] / (d["v20"] + .01)
    rr = {f: ranks(v) for f, v in raw.items()}
    score = {s: sum(FW[f] * rr[f].get(s, .5) for f in FW) for s in ASSETS}

    # Sideways/bearish high-risk overlay: use tradable defensive benchmarks,
    # never cash.  Crypto, energy and high-beta semiconductors are de-emphasized.
    breadth = np.mean([d["t30"] > 0 for d in series.values()])
    spx = series.get("SPX", {"t30": 0})["t30"]
    dispersion = np.std([d["t10"] for d in series.values()])
    risk = np.clip(1.5 * (.60 - breadth) + max(0, (-spx - .02) / .12)
                   + max(0, (dispersion - .025) / .05), 0, 1)
    for s in ("XAU", "US10Y", "CN10Y"):
        score[s] *= 1 + 1.35 * risk
    for s in ("BTC", "ETH", "WTI", "SOX", "NDX", "COPPER"):
        score[s] *= max(.20, 1 - .65 * risk)
    median_v = np.median([d["v20"] for d in series.values()])
    for s in ASSETS:
        v = series.get(s, {}).get("v20", median_v)
        score[s] *= np.clip(median_v / max(v, .003), .75, 1.20)
    target = weights(score)
    if abs(sum(target.values()) - 1.0) < 1e-8 and all(np.isfinite(v) and v >= 0 for v in target.values()):
        rebalance_to_weights(target)


def strategy():
    cross_asset_strategy()

