import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Current screener ensemble (8 active factors, all long direction).
FW = {"compression": .22, "breadth": .19, "stress": .16,
      "disp_rev": .12, "leadlag": .10, "ram": .08,
      "reversal": .07, "vol_rev": .06}
CADENCE = 10
_day = 0


def rank(values):
    good = sorted((s, x) for s, x in values.items() if np.isfinite(x))
    out = {s: .5 for s in ASSETS}
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = i / (len(good) - 1)
    elif good:
        out[good[0][0]] = .5
    return out


def bounded(raw):
    # Conservative concentration for a 15-name, high-risk cross-section.
    floor, cap = .035, .145
    w = {s: floor for s in ASSETS}
    free = 1.0 - floor * len(ASSETS)
    positive = {s: max(float(raw.get(s, .5)), .05) for s in ASSETS}
    den = sum(positive.values())
    for s in ASSETS:
        w[s] += free * positive[s] / den
    for _ in range(25):
        high = [s for s in ASSETS if w[s] > cap]
        if not high:
            break
        excess = sum(w[s] - cap for s in high)
        for s in high:
            w[s] = cap
        low = [s for s in ASSETS if s not in high]
        den = sum(positive[s] for s in low)
        for s in low:
            w[s] += excess * positive[s] / max(den, 1e-12)
    z = sum(w.values())
    return {s: max(0.0, w[s] / z) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % CADENCE:
        return
    stats = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=280)
        if df is None or len(df) < 80:
            continue
        close = np.asarray(df.sort_values("date").iloc[:-1]["close"], dtype=float)
        close = close[np.isfinite(close) & (close > 0)]
        if len(close) < 65:
            continue
        ret = close[1:] / close[:-1] - 1.0
        neg = ret[-60:][ret[-60:] < 0]
        dv = np.std(neg) if len(neg) >= 3 else np.std(ret[-20:])
        stats[s] = {
            "v10": max(np.std(ret[-10:]), .003),
            "v20": max(np.std(ret[-20:]), .003),
            "dv": max(dv, .003),
            "t3": close[-1] / close[-4] - 1.0,
            "t5": close[-1] / close[-6] - 1.0,
            "t10": close[-1] / close[-11] - 1.0,
            "t20": close[-1] / close[-21] - 1.0,
            "t30": close[-1] / close[-31] - 1.0,
        }
    if len(stats) < 10:
        return
    med5 = np.median([x["t5"] for x in stats.values()])
    med10 = np.median([x["t10"] for x in stats.values()])
    med20 = np.median([x["t20"] for x in stats.values()])
    dispersion = np.std([x["t10"] for x in stats.values()])
    raw = {f: {} for f in FW}
    for s, x in stats.items():
        # Proxies preserve the selected factor directions while avoiding future data.
        raw["compression"][s] = -x["v20"]
        raw["breadth"][s] = x["t30"] / (x["dv"] + .01)
        raw["stress"][s] = x["t10"] / (x["dv"] + .01)
        raw["ram"][s] = x["t20"] / (x["v20"] + .01)
        raw["leadlag"][s] = x["t5"] - med5
        # Small, conditional reversal overlays only when dispersion is elevated.
        raw["disp_rev"][s] = -(x["t10"] - med10) if dispersion > .025 else 0.0
        raw["reversal"][s] = -(x["t5"] - med5) if dispersion > .035 else 0.0
        raw["vol_rev"][s] = -x["t3"] / (x["v10"] + .01) if dispersion > .035 else 0.0
    ranks = {f: rank(v) for f, v in raw.items()}
    score = {s: sum(FW[f] * ranks[f][s] for f in FW) for s in ASSETS}
    breadth = np.mean([x["t30"] > 0 for x in stats.values()])
    market = stats.get("SPX", {"t30": 0.0})["t30"]
    risk = float(np.clip(1.5 * (.60 - breadth) + max(0.0, -market / .12)
                          + max(0.0, (dispersion - .025) / .05), 0.0, 1.0))
    # Full-investment defensive posture: use only tradable defensive assets.
    for s in ("XAU", "US10Y", "CN10Y"):
        score[s] *= 1.0 + 1.55 * risk
    for s in ("BTC", "ETH", "WTI", "SOX", "NDX", "COPPER"):
        score[s] *= max(.25, 1.0 - .70 * risk)
    medv = np.median([x["v20"] for x in stats.values()])
    for s in ASSETS:
        score[s] *= np.clip(medv / max(stats.get(s, {"v20": medv})["v20"], .003), .80, 1.15)
    target = bounded(score)
    if abs(sum(target.values()) - 1.0) < 1e-8 and set(target) == set(ASSETS):
        rebalance_to_weights(target)

