    _ensemble = json.load(fh)["selected_factors"]
FACTORS = [(x["factor_id"], float(x["weight"]), int(x["direction"]))
           for x in _ensemble]


def _window(fid):
    f = fid.lower()
    if "compression" in f: return 10, 60
    if "breadth" in f: return 30, 30
    if "stress" in f: return 5, 20
    if "leadlag" in f: return 5, 5
    if "reversal" in f or "residual" in f: return 3, 3
    if "agreement" in f: return 20, 60
    if "relative_risk" in f: return 20, 60
    return 20, 20


def _signal(df, fid):
    c = df.close.astype(float)
    r = c.pct_change()
    f = fid.lower(); a, b = _window(f)
    lr = np.log(c).diff()
    if "compression" in f:
        x = -(lr.rolling(a).std() / lr.rolling(b).std())
    elif "breadth" in f:
        x = (r.gt(0).rolling(a).mean() - .5)
    elif "stress" in f:
        x = -(lr.rolling(a).std() / lr.rolling(b).std())
    elif "leadlag" in f:
        x = c.pct_change(a) - c.pct_change(a).rolling(b).mean()
    elif "reversal" in f or "residual" in f:
        x = -c.pct_change(a)
    elif "agreement" in f:
        x = c.pct_change(a) * (c > c.rolling(b).mean()).astype(float)
    else:                           # quiet/relative-risk trend proxies
        x = c.pct_change(a)
    return x.replace([np.inf, -np.inf], np.nan).shift(1)


def _rank(vals, assets):
    good = sorted((v, a) for a, v in vals.items()
                  if v is not None and math.isfinite(v))
    out = {a: .5 for a in assets}
    for i, (_, a) in enumerate(good):
        out[a] = i / max(1, len(good)-1)
    return out


