"""15-asset, long-only, fully invested factor-ensemble strategy."""
import json, math
import numpy as np
from alphacrafter.sim.utils import (get_account_dict, get_stock_daily_data,
    rebalance_to_weights, register_hook)

ONLINE_START = "2026-07-16"
DATE_FILE = "../persistent/date.json"
STATE_FILE = "trader_state.json"
CAP = 0.16

# The live ensemble is read from the Screener contract; no more than 10 factors.
with open("factor_ensemble.json", encoding="utf-8") as f:
    _raw = json.load(f).get("selected_factors", [])[:10]
FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1))) for x in _raw]


def _signal(df, fid):
    c = df["close"].astype(float)
    r = c.pct_change()
    f = fid.lower()
    if "compression" in f:
        x = -(r.rolling(10).std() / r.rolling(60).std())
    elif "breadth" in f:
        x = r.gt(0).rolling(30).mean() - 0.5
    elif "stress" in f:
        x = -(r.rolling(5).std() / r.rolling(20).std())
    elif "leadlag" in f:
        x = c.pct_change(5) - c.pct_change(5).rolling(5).mean()
    elif "agreement" in f:
        x = c.pct_change(20) * (c > c.rolling(60).mean()).astype(float)
    elif "relative_risk" in f:
        x = c.pct_change(20) / r.rolling(20).std()
    else:  # quiet trend
        x = c.pct_change(20) / r.rolling(60).std()
    # Decisions see only the last completed session.
    return x.replace([np.inf, -np.inf], np.nan).shift(1)


def _rank(values, assets):
    good = sorted((v, a) for a, v in values.items() if v is not None and math.isfinite(v))
    out = {a: 0.5 for a in assets}
    for i, (_, a) in enumerate(good):
        out[a] = i / max(1, len(good) - 1)
    return out


def _cap_weights(w, assets):
    # Water-fill excess above the 16% asset cap, retaining a complete vector.
    for _ in range(30):
        excess = sum(max(0.0, w[a] - CAP) for a in assets)
        if excess < 1e-12:
            break
        room = [a for a in assets if w[a] < CAP - 1e-12]
        for a in assets:
            w[a] = min(w[a], CAP)
        den = sum(w[a] for a in room)
        if not room or den <= 0:
            break
        for a in room:
            w[a] += excess * w[a] / den
    z = sum(w.values())
    return {a: max(0.0, w[a] / z) for a in assets}


def _target(frames, assets):
    score = {a: 0.0 for a in assets}
    used = 0
    for fid, wt, direction in FACTORS:
        vals = {}
        for a in assets:
            try:
                s = _signal(frames[a], fid) if frames[a] is not None else None
                v = float(s.iloc[-1]) if s is not None else float("nan")
                vals[a] = v if math.isfinite(v) else None
            except Exception:
                vals[a] = None
        if sum(v is not None for v in vals.values()) < 8:
            continue
        ranks = _rank(vals, assets)
        for a in assets:
            score[a] += wt * (ranks[a] if direction > 0 else 1.0 - ranks[a])
        used += 1
    if not used:
        return {a: 1.0 / len(assets) for a in assets}, score
    # Small base allocation maintains diversification; ranking supplies tilt.
    w = {a: 0.025 + 0.10 * score[a] for a in assets}
    w = _cap_weights({a: x / sum(w.values()) for a, x in w.items()}, assets)
    weak = sum(frames[a] is not None and
               float(frames[a]["close"].iloc[-1]) < float(frames[a]["close"].rolling(20).mean().iloc[-1])
               for a in assets)
    if weak >= 10:
        for a in ("XAU", "US10Y", "CN10Y"):
            if a in w:
                w[a] += 0.025
        w = _cap_weights({a: x / sum(w.values()) for a, x in w.items()}, assets)
    return w, score


def _date_info():
    with open(DATE_FILE, encoding="utf-8") as f:
        d = json.load(f)
    return str(d["current_date"]), d.get("trading_days", [])


def _due(cur, days):
    if cur < ONLINE_START or cur not in days:
        return False
    try:
        with open(STATE_FILE, encoding="utf-8") as f:
            last = json.load(f).get("last_proposal_date")
    except Exception:
        last = None
    if last in days:
        return days.index(cur) - days.index(last) >= 10
    return True


@register_hook
def strategy_hook():
    cur, days = _date_info()
    if not _due(cur, days):
        return
    account = get_account_dict()
    assets = list(account.get("watch_list", []))
    if len(assets) != 15 or len(set(assets)) != 15 or not FACTORS:
        return
    frames = {}
    for a in assets:
        try:
            d = get_stock_daily_data(symbol=a, days=170)
            frames[a] = None if d is None or len(d) < 100 else d.sort_values("date").set_index("date")
        except Exception:
            frames[a] = None
    weights, score = _target(frames, assets)
    mean = float(np.mean(list(score.values())))
    scale = max(1e-9, (max(score.values()) - min(score.values())) / 2.0)
    forecasts = {a: float(np.clip(0.04 * (score[a] - mean) / scale, -0.05, 0.05)) for a in assets}
    rebalance_to_weights(weights, forecast_returns=forecasts,
                         factor_ids=[x[0] for x in FACTORS], horizon_days=10)
    with open(STATE_FILE, "w", encoding="utf-8") as f:
        json.dump({"last_proposal_date": cur}, f)

strategy_hook

