"""Lagged cross-sectional factor ensemble for the 15-asset benchmark."""
import json
import math
import numpy as np
import pandas as pd
from alphacrafter.sim.utils import (
    get_account_dict, get_stock_daily_data, rebalance_to_weights, register_hook
)

START = "2026-07-16"
DATE_FILE = "../persistent/date.json"
STATE_FILE = "trader_state.json"
ASSETS = {"000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"}
CAP = 0.16
with open("factors/factor_ensemble.json", encoding="utf-8") as fh:
    FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1)))
               for x in json.load(fh).get("selected_factors", [])[:10]]


def factor_value(frame, fid, peer):
    close = frame["close"].astype(float)
    ret = close.pct_change()
    name = fid.lower()
    if "risk_adjusted_trend_reversal" in name:
        x = -(close.pct_change(60) / (np.sqrt(60) * ret.rolling(60).std() + 1e-8)) * ret.gt(0).rolling(60).mean()
    elif "dispersion_5d_contraction" in name:
        cross_med = peer.median(axis=1)
        dispersion = peer.sub(cross_med, axis=0).abs().mean(axis=1)
        active = dispersion < dispersion.rolling(20).median()
        x = -(close.pct_change(5) - cross_med.rolling(5).sum()) * active.astype(float)
    elif "dispersion_scaled_range5" in name:
        cross_med = peer.median(axis=1)
        dispersion = peer.sub(cross_med, axis=0).abs().mean(axis=1)
        x = -(close.pct_change(5) - cross_med.rolling(5).sum()) / (dispersion.rolling(5).mean() + 1e-8)
    elif "volatility_compression" in name:
        x = -(ret.rolling(10).std() / (ret.rolling(60).std() + 1e-8))
    elif "downside_adjusted_breadth" in name:
        downside = ret.where(ret < 0).rolling(30).std()
        x = (ret.gt(0).rolling(30).mean() - 0.5) / (downside + 1e-8)
    elif "risk_adjusted_momentum" in name:
        x = close.pct_change(20) / (ret.rolling(20).std() + 1e-8)
    elif "stress_downside_shock" in name:
        x = -ret.rolling(5).sum() / (ret.rolling(20).std() + 1e-8)
    elif "peer_median_leadlag" in name:
        x = close.pct_change(5) - peer.median(axis=1).pct_change(5)
    elif "relative_risk_trend" in name:
        x = close.pct_change(20) / (ret.rolling(20).std() + 1e-8)
    else:
        x = close.pct_change(20) / (ret.rolling(60).std() + 1e-8)
    x = x.replace([np.inf, -np.inf], np.nan).shift(1)
    value = x.iloc[-1] if len(x) else np.nan
    return float(value) if pd.notna(value) and math.isfinite(float(value)) else None


def percentile(values):
    valid = sorted(v for v in values.values() if v is not None and math.isfinite(v))
    if not valid:
        return {a: 0.5 for a in values}
    out = {}
    for a, v in values.items():
        out[a] = (sum(q <= v for q in valid) - 1) / max(1, len(valid) - 1) if v is not None else 0.5
    return out


def make_portfolio(frames, assets):
    peer = pd.DataFrame({a: frames[a]["close"].pct_change() for a in assets})
    score = {a: 0.0 for a in assets}
    for fid, factor_weight, direction in FACTORS:
        raw = {a: factor_value(frames[a], fid, peer) for a in assets}
        ranks = percentile(raw)
        for a in assets:
            score[a] += factor_weight * (ranks[a] if direction > 0 else 1.0 - ranks[a])
    # Positive floor gives every tradable a nonzero defensive allocation.
    weights = {a: 0.025 + 0.10 * score[a] for a in assets}
    total = sum(weights.values())
    weights = {a: v / total for a, v in weights.items()}
    weak = sum(frames[a]["close"].iloc[-1] < frames[a]["close"].rolling(20).mean().iloc[-1] for a in assets)
    if weak >= 10:
        for a in ("XAU", "US10Y", "CN10Y"):
            weights[a] += 0.025
        total = sum(weights.values())
        weights = {a: v / total for a, v in weights.items()}
    # Enforce a 16% single-asset cap while preserving full investment.
    for _ in range(30):
        over = [a for a in assets if weights[a] > CAP]
        if not over:
            break
        excess = sum(weights[a] - CAP for a in over)
        for a in over:
            weights[a] = CAP
        room = [a for a in assets if weights[a] < CAP - 1e-12]
        denom = sum(weights[a] for a in room)
        if not room or denom <= 0:
            break
        for a in room:
            weights[a] += excess * weights[a] / denom
    total = sum(weights.values())
    weights = {a: max(0.0, v / total) for a, v in weights.items()}
    return weights, score


def is_due(current, trading_days):
    if current < START or current not in trading_days:
        return False
    try:
        with open(STATE_FILE, encoding="utf-8") as fh:
            previous = json.load(fh).get("last_proposal_date")
    except Exception:
        previous = None
    return previous not in trading_days or trading_days.index(current) - trading_days.index(previous) >= 10


@register_hook
def strategy_hook():
    with open(DATE_FILE, encoding="utf-8") as fh:
        date_info = json.load(fh)
    current = str(date_info["current_date"])
    if not is_due(current, date_info.get("trading_days", [])):
        return
    account = get_account_dict()
    assets = list(account.get("watch_list", []))
    if len(assets) != 15 or set(assets) != ASSETS or not FACTORS:
        return
    frames = {}
    for asset in assets:
        data = get_stock_daily_data(symbol=asset, days=180)
        frames[asset] = None if data is None or len(data) < 100 else data.sort_values("date").set_index("date")
    if any(frame is None for frame in frames.values()):
        return
    target, score = make_portfolio(frames, assets)
    center = float(np.mean(list(score.values())))
    scale = max(1e-9, (max(score.values()) - min(score.values())) / 2.0)
    forecast = {a: float(np.clip(0.04 * (score[a] - center) / scale, -0.05, 0.05)) for a in assets}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[x[0] for x in FACTORS], horizon_days=10)
    with open(STATE_FILE, "w", encoding="utf-8") as fh:
        json.dump({"last_proposal_date": current}, fh)

strategy_hook

