import json, math
import numpy as np
from alphacrafter.sim.utils import get_account_dict, get_stock_daily_data, rebalance_to_weights, register_hook

START = "2026-07-16"
DATE_FILE = "../persistent/date.json"
STATE_FILE = "trader_state.json"
CAP = 0.16
ASSET_SET = {"000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"}
with open("factor_ensemble.json", encoding="utf-8") as f:
    FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1)))
               for x in json.load(f).get("selected_factors", [])[:10]]


def signal(df, fid, peer_returns):
    c = df.close.astype(float)
    r = c.pct_change()
    f = fid.lower()
    if "dispersion" in f:
        own = c.pct_change(5)
        med = peer_returns.rolling(5).median().median(axis=1)
        disp = peer_returns.rolling(5).std().mean(axis=1)
        threshold = disp.rolling(20).median()
        active = bool(len(disp) and np.isfinite(disp.iloc[-1]) and np.isfinite(threshold.iloc[-1]) and disp.iloc[-1] < threshold.iloc[-1])
        x = -(own - med) if active else own * 0.0
    elif "compression" in f:
        x = -(r.rolling(10).std() / r.rolling(60).std())
    elif "breadth" in f:
        x = r.gt(0).rolling(30).mean() - 0.5
    elif "stress" in f:
        x = -(r.rolling(5).std() / r.rolling(20).std())
    elif "leadlag" in f:
        x = c.pct_change(5) - c.pct_change(5).rolling(5).mean()
    elif "relative_risk" in f:
        x = c.pct_change(20) / r.rolling(20).std()
    else:
        x = c.pct_change(20) / r.rolling(60).std()
    x = x.replace([np.inf, -np.inf], np.nan).shift(1)
    return float(x.iloc[-1]) if len(x) and math.isfinite(float(x.iloc[-1])) else None


def rank(vals, assets):
    good = sorted((v, a) for a, v in vals.items() if v is not None and math.isfinite(v))
    out = {a: .5 for a in assets}
    for i, (_, a) in enumerate(good):
        out[a] = i / max(1, len(good)-1)
    return out


def weights(frames, assets):
    rets = {a: frames[a].close.astype(float).pct_change() for a in assets}
    peer = __import__('pandas').DataFrame(rets)
    score = {a: 0.0 for a in assets}
    for fid, wt, direction in FACTORS:
        vals = {a: signal(frames[a], fid, peer) for a in assets}
        if sum(v is not None for v in vals.values()) < 8:
            continue
        rr = rank(vals, assets)
        for a in assets:
            score[a] += wt * (rr[a] if direction > 0 else 1 - rr[a])
    w = {a: .025 + .10 * score[a] for a in assets}
    z = sum(w.values())
    w = {a: x / z for a, x in w.items()}
    weak = sum(float(frames[a].close.iloc[-1]) < float(frames[a].close.rolling(20).mean().iloc[-1]) for a in assets)
    if weak >= 10:
        for a in ("XAU", "US10Y", "CN10Y"):
            w[a] += .025
        z = sum(w.values())
        w = {a: x / z for a, x in w.items()}
    for _ in range(20):
        excess = sum(max(0., x - CAP) for x in w.values())
        if excess < 1e-10:
            break
        room = [a for a in assets if w[a] < CAP - 1e-10]
        for a in assets:
            w[a] = min(w[a], CAP)
        den = sum(w[a] for a in room)
        if not room or den <= 0:
            break
        for a in room:
            w[a] += excess * w[a] / den
    z = sum(w.values())
    return {a: max(0., x / z) for a, x in w.items()}, score


def due(cur, days):
    if cur < START or cur not in days:
        return False
    try:
        with open(STATE_FILE, encoding="utf-8") as f:
            last = json.load(f).get("last_proposal_date")
    except Exception:
        last = None
    return last not in days or days.index(cur) - days.index(last) >= 10


@register_hook
def strategy_hook():
    with open(DATE_FILE, encoding="utf-8") as f:
        d = json.load(f)
    cur, days = str(d["current_date"]), d.get("trading_days", [])
    if not due(cur, days):
        return
    account = get_account_dict()
    assets = list(account.get("watch_list", []))
    if set(assets) != ASSET_SET or len(assets) != 15 or not FACTORS:
        return
    frames = {}
    for a in assets:
        x = get_stock_daily_data(symbol=a, days=180)
        frames[a] = None if x is None or len(x) < 100 else x.sort_values("date").set_index("date")
    if any(x is None for x in frames.values()):
        return
    w, score = weights(frames, assets)
    mean = np.mean(list(score.values()))
    span = max(1e-9, (max(score.values()) - min(score.values())) / 2)
    forecasts = {a: float(np.clip(.04 * (score[a] - mean) / span, -.05, .05)) for a in assets}
    rebalance_to_weights(w, forecast_returns=forecasts, factor_ids=[x[0] for x in FACTORS], horizon_days=10)
    with open(STATE_FILE, "w", encoding="utf-8") as f:
