from alphacrafter.sim.utils import get_account_dict, get_stock_daily_data, rebalance_to_weights, register_hook

START = "2026-07-16"
DATE_FILE = "../persistent/date.json"
STATE_FILE = "trader_state.json"
ASSETS = {"000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"}
CAP = 0.16
with open("factors/factor_ensemble.json", encoding="utf-8") as f:
    FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1)))
               for x in json.load(f).get("selected_factors", [])[:10]]


def factor_value(df, fid, peer):
    close = df["close"].astype(float)
    r = close.pct_change()
    n = fid.lower()
    if "macro_breadth_shock" in n:
        breadth = peer.gt(0).mean(axis=1) - 0.5
        shock = peer.mean(axis=1).rolling(5).sum()
        x = -(shock - shock.rolling(60).mean()) * breadth
    elif "risk_adjusted_trend_reversal" in n:
        x = -(close.pct_change(60) / (np.sqrt(60) * r.rolling(60).std() + 1e-8)) * r.gt(0).rolling(60).mean()
    elif "quiet_trend" in n:
        x = close.pct_change(20) / (r.rolling(20).std() + 1e-8) * (r.rolling(10).std() < r.rolling(60).std()).astype(float)
    elif "relative_risk_trend" in n:
        x = close.pct_change(20) / (r.rolling(20).std() + 1e-8)
    elif "volatility_compression" in n:
        x = -(r.rolling(10).std() / (r.rolling(60).std() + 1e-8))
    elif "downside_adjusted_breadth" in n:
        down = r.where(r < 0).rolling(30).std()
        x = (r.gt(0).rolling(30).mean() - 0.5) / (down + 1e-8)
    elif "dispersion_5d_contraction" in n:
        med = peer.median(axis=1)
        disp = peer.sub(med, axis=0).abs().mean(axis=1)
        x = -(r.rolling(5).sum() - med.rolling(5).sum()) * (disp < disp.rolling(20).median())
    elif "stress_downside_shock" in n:
        x = -r.rolling(5).sum() / (r.rolling(20).std() + 1e-8)
    elif "relative_downside_momentum" in n:
        x = r.where(r < 0).rolling(60).sum() / (r.rolling(60).std() + 1e-8)
    elif "downside_volatility_asymmetry" in n:
        up = r.where(r > 0).rolling(30).std()
        down = r.where(r < 0).rolling(30).std()
        x = up / (down + 1e-8)
    else:
        x = close.pct_change(20) / (r.rolling(60).std() + 1e-8)
    x = x.replace([np.inf, -np.inf], np.nan).shift(1)
    v = x.iloc[-1]
    return float(v) if pd.notna(v) and math.isfinite(float(v)) else None


def ranks(values):
    valid = sorted(v for v in values.values() if v is not None and math.isfinite(v))
    return {a: ((sum(v <= x for v in valid) - 1) / max(1, len(valid)-1)
                if x is not None and valid else 0.5) for a, x in values.items()}


def portfolio(frames, assets):
    peer = pd.DataFrame({a: frames[a]["close"].pct_change() for a in assets})
    score = {a: 0.0 for a in assets}
    for fid, weight, direction in FACTORS:
        rr = ranks({a: factor_value(frames[a], fid, peer) for a in assets})
        for a in assets:
            score[a] += weight * (rr[a] if direction > 0 else 1.0 - rr[a])
    # Small floor keeps the online portfolio fully invested and diversified.
    w = {a: 0.025 + 0.10 * score[a] for a in assets}
    # Medium-high risk: add a modest defensive tilt when breadth is weak.
    weak = sum(frames[a]["close"].iloc[-1] < frames[a]["close"].rolling(20).mean().iloc[-1] for a in assets)
    if weak >= 10:
        for a in ("XAU", "US10Y", "CN10Y"):
            w[a] += 0.025
    s = sum(w.values())
    w = {a: x / s for a, x in w.items()}
    # Concentration control, followed by exact normalization.
    for _ in range(30):
        over = [a for a in assets if w[a] > CAP]
        if not over:
            break
        excess = sum(w[a] - CAP for a in over)
        for a in over:
            w[a] = CAP
        room = [a for a in assets if w[a] < CAP - 1e-12]
        denom = sum(w[a] for a in room)
        if not room or denom <= 0:
            break
        for a in room:
            w[a] += excess * w[a] / denom
    s = sum(w.values())
    return {a: max(0.0, w[a] / s) for a in assets}, score


def due(date, days):
    if date < START or date not in days:
        return False
    try:
        with open(STATE_FILE, encoding="utf-8") as f:
            prior = json.load(f).get("last_proposal_date")
    except Exception:
        prior = None
    return prior not in days or days.index(date) - days.index(prior) >= 10


@register_hook
def strategy_hook():
    with open(DATE_FILE, encoding="utf-8") as f:
        info = json.load(f)
    date = str(info["current_date"])
    if not due(date, info.get("trading_days", [])):
        return
    account = get_account_dict()
    assets = list(account.get("watch_list", []))
    if len(assets) != 15 or set(assets) != ASSETS or not FACTORS:
        return
    frames = {}
    for a in assets:
        d = get_stock_daily_data(symbol=a, days=180)
        frames[a] = None if d is None or len(d) < 100 else d.sort_values("date").set_index("date")
    if any(x is None for x in frames.values()):
        return
    target, score = portfolio(frames, assets)
    center = float(np.mean(list(score.values())))
    scale = max(1e-9, (max(score.values()) - min(score.values())) / 2.0)
    forecast = {a: float(np.clip(0.04 * (score[a] - center) / scale, -0.05, 0.05)) for a in assets}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[x[0] for x in FACTORS], horizon_days=10)
    with open(STATE_FILE, "w", encoding="utf-8") as f:
        json.dump({"last_proposal_date": date}, f)

