"""Full-investment, lagged cross-sectional ensemble strategy for the 15-asset worldline."""
import json, math
import numpy as np
import pandas as pd
from alphacrafter.sim.utils import (get_account_dict, get_stock_daily_data,
    rebalance_to_weights, register_hook)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
START = "2026-07-16"
DATE_FILE = "../persistent/date.json"
STATE_FILE = "trader_state.json"
CAP, FLOOR = 0.16, 0.025
with open("factors/factor_ensemble.json", encoding="utf-8") as f:
    _ens = json.load(f)
FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1)))
           for x in _ens.get("selected_factors", [])[:10]]


def _raw(df, fid, peer):
    c = df["close"].astype(float); r = c.pct_change(); n = fid.lower()
    if "quiet_trend" in n:
        x = c.pct_change(20) / (r.rolling(20).std()+1e-8)
        x = x.where(r.rolling(10).std() < r.rolling(60).std(), 0.0)
    elif "relative_risk_trend" in n:
        x = c.pct_change(20)/(r.rolling(20).std()+1e-8)
    elif "volatility_compression" in n:
        x = -(r.rolling(10).std()/(r.rolling(60).std()+1e-8))
    elif "downside_adjusted_breadth" in n:
        dn = r.where(r < 0).rolling(30).std()
        x = (r.gt(0).rolling(30).mean()-0.5)/(dn+1e-8)
    elif "dispersion_5d_contraction" in n:
        med = peer.median(axis=1); disp = peer.sub(med, axis=0).abs().mean(axis=1)
        x = -(r.rolling(5).sum()-med.rolling(5).sum()) * (disp < disp.rolling(20).median())
    elif "dispersion_stress_reversal" in n:
        med = peer.median(axis=1); disp = peer.sub(med, axis=0).abs().mean(axis=1)
        x = -(r.rolling(1).sum()-med) * (disp > disp.rolling(20).median())
    elif "risk_adjusted_trend_reversal" in n:
        x = -(c.pct_change(60)/(r.rolling(60).std()+1e-8))
    elif "macro_breadth_shock" in n:
        breadth = peer.gt(0).mean(axis=1)-0.5
        shock = peer.mean(axis=1).rolling(5).sum()
        x = -(shock-shock.rolling(60).mean())*breadth
    else:
        x = c.pct_change(20)/(r.rolling(60).std()+1e-8)
    return x.replace([np.inf, -np.inf], np.nan).shift(1).iloc[-1]


def _rank(values):
    good = [float(v) for v in values.values() if v is not None and pd.notna(v) and math.isfinite(float(v))]
    return {a: ((sum(z <= float(v) for z in good)-1)/max(1, len(good)-1)
               if a in values and values[a] is not None and pd.notna(values[a]) and math.isfinite(float(values[a])) else .5)
            for a, v in values.items()}


def build(frames):
    peer = pd.DataFrame({a: frames[a]["close"].pct_change() for a in ASSETS})
    score = {a: 0.0 for a in ASSETS}
    for fid, wt, direction in FACTORS:
        q = _rank({a: _raw(frames[a], fid, peer) for a in ASSETS})
        for a in ASSETS: score[a] += wt * (q[a] if direction > 0 else 1-q[a])
    # Floor plus modest score tilt; defensive tradables receive a stress overlay.
    w = {a: FLOOR + 0.10*score[a] for a in ASSETS}
    weak = sum(frames[a]["close"].iloc[-1] < frames[a]["close"].rolling(20).mean().iloc[-1] for a in ASSETS)
    if weak >= 9:
        for a in ("XAU", "US10Y", "CN10Y"): w[a] += .025
    w = {a: max(0.0, v) for a, v in w.items()}
    for _ in range(25):
        s = sum(w.values()); w = {a: v/s for a,v in w.items()}
        over = [a for a in ASSETS if w[a] > CAP]
        if not over: break
        excess = sum(w[a]-CAP for a in over)
        for a in over: w[a] = CAP
        room = [a for a in ASSETS if a not in over]
        base = sum(w[a] for a in room)
        for a in room: w[a] += excess*w[a]/base
    s = sum(w.values()); w = {a: w[a]/s for a in ASSETS}
    center = sum(score.values())/len(ASSETS)
    spread = max(1e-8, (max(score.values())-min(score.values()))/2)
    forecast = {a: float(np.clip(.04*(score[a]-center)/spread, -.05, .05)) for a in ASSETS}
    return w, forecast


@register_hook
def strategy_hook():
    info = json.load(open(DATE_FILE, encoding="utf-8"))
    date, cal = str(info["current_date"]), info.get("trading_days", [])
    if date < START or date not in cal: return
    try: prior = json.load(open(STATE_FILE, encoding="utf-8")).get("last_proposal_date")
    except Exception: prior = None
    if prior and prior in cal and cal.index(date)-cal.index(prior) < 10: return
    account = get_account_dict()
    if set(account.get("watch_list", [])) != set(ASSETS): return
    frames = {}
    for a in ASSETS:
        d = get_stock_daily_data(symbol=a, days=180)
        if d is None or len(d) < 100: return
        frames[a] = d.sort_values("date").set_index("date")
    target, forecast = build(frames)
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[f[0] for f in FACTORS], horizon_days=10)
    json.dump({"last_proposal_date": date}, open(STATE_FILE, "w", encoding="utf-8"))

