"""Lagged full-investment cross-asset factor ensemble strategy."""
import json, math
import numpy as np
import pandas as pd
from alphacrafter.sim.utils import get_account_dict, get_stock_daily_data, rebalance_to_weights, register_hook

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
START = "2026-07-16"
DATE_FILE = "../persistent/date.json"
STATE_FILE = "trader_state.json"
FLOOR, CAP = 0.025, 0.16
with open("factors/factor_ensemble.json", encoding="utf-8") as f:
    _ensemble = json.load(f)
FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1)))
           for x in _ensemble.get("selected_factors", [])[:10]]


def raw_signal(df, fid, peer):
    close = df["close"].astype(float)
    ret = close.pct_change()
    name = fid.lower()
    if "quiet_trend" in name:
        x = close.pct_change(20) / (ret.rolling(20).std() + 1e-8)
        x = x.where(ret.rolling(10).std() < ret.rolling(60).std(), 0.0)
    elif "relative_risk_trend" in name:
        x = close.pct_change(20) / (ret.rolling(20).std() + 1e-8)
    elif "volatility_compression" in name:
        x = -(ret.rolling(10).std() / (ret.rolling(60).std() + 1e-8))
    elif "downside_adjusted_breadth" in name:
        downside = ret.where(ret < 0).rolling(30).std()
        x = (ret.gt(0).rolling(30).mean() - 0.5) / (downside + 1e-8)
    elif "dispersion_5d_contraction" in name:
        med = peer.median(axis=1)
        dispersion = peer.sub(med, axis=0).abs().mean(axis=1)
        x = -(ret.rolling(5).sum() - med.rolling(5).sum()) * (dispersion < dispersion.rolling(20).median())
    elif "risk_adjusted_trend_reversal" in name:
        x = -(close.pct_change(60) / (ret.rolling(60).std() + 1e-8))
    elif "vix_stress_reversal" in name:
        # Observation-only stress proxy: breadth shock, then cross-sectional reversal.
        breadth = peer.gt(0).mean(axis=1) - 0.5
        shock = peer.mean(axis=1).rolling(5).sum()
        stress = (breadth < breadth.rolling(60).quantile(0.35)) | (shock < shock.rolling(60).quantile(0.35))
        med = peer.median(axis=1)
        x = (-(ret.rolling(5).sum() - med.rolling(5).sum())).where(stress, 0.0)
    elif "macro_breadth_shock" in name:
        breadth = peer.gt(0).mean(axis=1) - 0.5
        shock = peer.mean(axis=1).rolling(5).sum()
        x = -(shock - shock.rolling(60).mean()) * breadth
    else:
        x = close.pct_change(20) / (ret.rolling(60).std() + 1e-8)
    return x.replace([np.inf, -np.inf], np.nan).shift(1).iloc[-1]


def ranks(values):
    valid = [float(v) for v in values.values() if v is not None and pd.notna(v) and math.isfinite(float(v))]
    out = {}
    for asset, value in values.items():
        ok = value is not None and pd.notna(value) and math.isfinite(float(value))
        out[asset] = (sum(z <= float(value) for z in valid) - 1) / max(1, len(valid) - 1) if ok else 0.5
    return out


def build(frames):
    peer = pd.DataFrame({a: frames[a]["close"].pct_change() for a in ASSETS})
    score = {a: 0.0 for a in ASSETS}
    for fid, weight, direction in FACTORS:
        q = ranks({a: raw_signal(frames[a], fid, peer) for a in ASSETS})
        for a in ASSETS:
            score[a] += weight * (q[a] if direction > 0 else 1.0 - q[a])
    weights = {a: FLOOR + 0.10 * score[a] for a in ASSETS}
    weak = sum(frames[a]["close"].iloc[-1] < frames[a]["close"].rolling(20).mean().iloc[-1] for a in ASSETS)
    if weak >= 9:
        for a in ("XAU", "US10Y", "CN10Y"):
            weights[a] += 0.025
    for a in ASSETS:
        weights[a] = max(0.0, weights[a])
    for _ in range(30):
        total = sum(weights.values())
        weights = {a: v / total for a, v in weights.items()}
        over = [a for a in ASSETS if weights[a] > CAP]
        if not over:
            break
        excess = sum(weights[a] - CAP for a in over)
        for a in over:
            weights[a] = CAP
        room = [a for a in ASSETS if a not in over]
        room_total = sum(weights[a] for a in room)
        for a in room:
            weights[a] += excess * weights[a] / max(room_total, 1e-12)
    total = sum(weights.values())
    weights = {a: v / total for a, v in weights.items()}
    center = sum(score.values()) / len(ASSETS)
    spread = max(1e-8, (max(score.values()) - min(score.values())) / 2)
    forecast = {a: float(np.clip(0.04 * (score[a] - center) / spread, -0.05, 0.05)) for a in ASSETS}
    return weights, forecast


@register_hook
def strategy_hook():
    with open(DATE_FILE, encoding="utf-8") as f:
        info = json.load(f)
    date, calendar = str(info["current_date"]), info.get("trading_days", [])
    if date < START or date not in calendar:
        return
    try:
        with open(STATE_FILE, encoding="utf-8") as f:
            prior = json.load(f).get("last_proposal_date")
