import json, math
import numpy as np
import pandas as pd
from alphacrafter.sim.utils import (
    get_account_dict, get_stock_daily_data, rebalance_to_weights, register_hook
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
          "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
START = "2026-07-16"
DATE_FILE, STATE_FILE = "../persistent/date.json", "trader_state.json"
FLOOR, CAP = 0.025, 0.16

with open("factors/factor_ensemble.json", encoding="utf-8") as f:
    _ensemble = json.load(f)
FACTORS = [(x["factor_id"], float(x["weight"]), int(x.get("direction", 1)))
           for x in _ensemble.get("selected_factors", [])[:10]]


def signal(df, fid, peer):
    c = df["close"].astype(float)
    r = c.pct_change()
    v10, v20, v60 = r.rolling(10).std(), r.rolling(20).std(), r.rolling(60).std()
    m3, m5, m10, m20, m60 = (c.pct_change(k) for k in (3, 5, 10, 20, 60))
    downside = r.where(r < 0).rolling(60).std()
    breadth = peer.gt(0).mean(axis=1)
    stress = (breadth < 0.35) & (peer.std(axis=1) > peer.std(axis=1).rolling(60).median())
    n = fid.lower()
    if "volatility_compression" in n:
        x = -(v10 / (v60 + 1e-8))
    elif "relative_downside_momentum" in n:
        x = m60 / (downside + 1e-8)
    elif "quiet_trend" in n:
        x = (m20 / (v20 + 1e-8)).where(v20 < v60, 0.0)
    elif "relative_risk_trend" in n:
        x = m20 / (v20 + 1e-8)
    elif "risk_adjusted_trend_reversal" in n:
        x = -m60 / (v60 + 1e-8)
    elif "dispersion_capitulation_reversal" in n:
        x = (-m5).where(stress, 0.0) / (v20 + 1e-8)
    elif "stress_gated_reversal" in n:
        x = (-m3).where(stress, 0.0) / (v10 + 1e-8)
    elif "downside_volatility_asymmetry" in n:
        x = -(downside / (v60 + 1e-8))
    else:
        x = m20 / (v60 + 1e-8)
    # Lag one completed session: no current-day look-ahead.
    return x.replace([np.inf, -np.inf], np.nan).shift(1).iloc[-1]


def percentile(values):
    good = [float(v) for v in values.values()
            if v is not None and pd.notna(v) and math.isfinite(float(v))]
    out = {}
    for a, v in values.items():
        valid = v is not None and pd.notna(v) and math.isfinite(float(v))
        out[a] = (sum(z <= float(v) for z in good) - 1) / max(1, len(good) - 1) if valid else 0.5
    return out


def construct(frames):
    peer = pd.DataFrame({a: frames[a]["close"].pct_change() for a in ASSETS})
    score = {a: 0.0 for a in ASSETS}
    for fid, fw, direction in FACTORS:
        q = percentile({a: signal(frames[a], fid, peer) for a in ASSETS})
        for a in ASSETS:
            score[a] += fw * (q[a] if direction > 0 else 1.0 - q[a])

    # Rank-based diversified base; then tilt defensive tradable assets in broad weakness.
    weights = {a: FLOOR + 0.10 * score[a] for a in ASSETS}
    weak = sum(frames[a]["close"].iloc[-1] < frames[a]["close"].rolling(20).mean().iloc[-1]
               for a in ASSETS)
    if weak >= 8:
        for a in ("XAU", "US10Y", "CN10Y"):
            weights[a] += 0.035

    # Iterative cap redistribution preserves non-negative, fully invested weights.
    for _ in range(50):
        total = sum(weights.values())
        weights = {a: v / total for a, v in weights.items()}
        over = [a for a in ASSETS if weights[a] > CAP]
        if not over:
            break
        excess = sum(weights[a] - CAP for a in over)
        for a in over:
            weights[a] = CAP
        room = [a for a in ASSETS if a not in over]
        room_total = sum(weights[a] for a in room)
        for a in room:
            weights[a] += excess * weights[a] / max(room_total, 1e-12)
    weights = {a: v / sum(weights.values()) for a, v in weights.items()}

    mid = sum(score.values()) / len(ASSETS)
    scale = max((max(score.values()) - min(score.values())) / 2, 1e-8)
    forecast = {a: float(np.clip(0.04 * (score[a] - mid) / scale, -0.05, 0.05))
                for a in ASSETS}
    return weights, forecast


@register_hook
def strategy_hook():
    with open(DATE_FILE, encoding="utf-8") as f:
        info = json.load(f)
    date, days = str(info["current_date"]), info.get("trading_days", [])
    if date < START or date not in days:
